31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        Collection<Owner> existingOwners = this.clinicService.findAllOwners();
105	        if (DailyRegistrationLimit.isReached(existingOwners)) {
106	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
107	        }
108	        HouseholdDuplicates.assignHousehold(owner, existingOwners, ownerFieldsDto.getSharesHousehold());
109	        if (IdentityKey.isDuplicate(owner, existingOwners)
110	            || CityCapacity.isAtCapacity(owner, existingOwners)) {
111	            return new ResponseEntity<>(HttpStatus.CONFLICT);
112	        }
113	        owner.setNamesakeCount(Namesakes.count(owner, existingOwners));
114	        owner.setCustomerCode(CustomerCodes.build(owner, existingOwners));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        ownerDto.setBulkSignupWarning(BulkSignupWarning.isTriggered(existingOwners));
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
126	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
127	        if (currentOwner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        currentOwner.setAddress(ownerFieldsDto.getAddress());
131	        currentOwner.setCity(ownerFieldsDto.getCity());
132	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
133	        currentOwner.setLastName(ownerFieldsDto.getLastName());
134	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
135	        this.clinicService.saveOwner(currentOwner);
136	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Transactional
141	    @Override
142	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        this.clinicService.deleteOwner(owner);
148	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        HttpHeaders headers = new HttpHeaders();
159	        Pet pet = petMapper.toPet(petFieldsDto);
160	        owner.setId(ownerId);
161	        pet.setOwner(owner);
162	        pet.getType().setName(null);
163	        this.clinicService.savePet(pet);
164	        PetDto petDto = petMapper.toPetDto(pet);
165	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
166	            .buildAndExpand(pet.getId()).toUri());
167	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner != null) {
175	            Pet currentPet = this.clinicService.findPetById(petId);
176	            if (currentPet != null) {
177	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
178	                currentPet.setName(petFieldsDto.getName());
179	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
180	                this.clinicService.savePet(currentPet);
181	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	            }
183	        }
184	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
190	        HttpHeaders headers = new HttpHeaders();
191	        Visit visit = visitMapper.toVisit(visitFieldsDto);
192	        Pet pet = new Pet();
193	        pet.setId(petId);
194	        visit.setPet(pet);
195	        this.clinicService.saveVisit(visit);
196	        VisitDto visitDto = visitMapper.toVisitDto(visit);
197	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
198	            .buildAndExpand(visit.getId()).toUri());
199	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
200	    }
201	
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner != null) {
208	            Pet pet = owner.getPet(petId);
209	            if (pet != null) {
210	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	}
